package com.shilapi.xcertplay.menglong;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;
import com.shilapi.xcertplay.HudEdgeMask;import com.shilapi.xcertplay.HudEdgeMaskView;
/** V3's original edge mask view, with no pixel color adjustment. */
public final class V3HudFrame extends FrameLayout {
 private HudEdgeMaskView mask;
 public V3HudFrame(Context c){super(c);setBackgroundColor(android.graphics.Color.TRANSPARENT);setClipChildren(true);mask=new HudEdgeMaskView(c);addView(mask,new FrameLayout.LayoutParams(-1,-1));refresh();}
 public void refresh(){if(mask==null)return;android.content.SharedPreferences p=getContext().getSharedPreferences("menglong_v3_hud_edge",0);mask.setMask(new HudEdgeMask(value(p,"left"),value(p,"right"),value(p,"top"),value(p,"bottom")));View video=null;for(int i=0;i<getChildCount();i++)if(getChildAt(i) instanceof TextureView){video=getChildAt(i);break;}if(video!=null&&video.getWidth()>0)mask.setPictureBounds(video.getLeft(),video.getTop(),video.getRight(),video.getBottom());else mask.setPictureBounds(0,0,getWidth(),getHeight());if(getChildAt(getChildCount()-1)!=mask)((View)mask).bringToFront();}
 private static float value(android.content.SharedPreferences p,String key){return Math.max(0,Math.min(40,p.getInt(key,0)))/100f;}
 protected void onLayout(boolean changed,int l,int t,int r,int b){super.onLayout(changed,l,t,r,b);refresh();}
 public static void settings(Activity a){android.content.SharedPreferences p=a.getSharedPreferences("menglong_v3_hud_edge",0);LinearLayout body=new LinearLayout(a);body.setOrientation(1);body.setPadding(20,16,20,16);TextView hint=new TextView(a);hint.setText("使用 V3 原版渐变黑色边缘遮罩，只处理 HUD 地图边缘，不改变仪表颜色。0% 不遮挡；夜间背景仍来自高德原画面。");body.addView(hint);String[] keys={"left","right","top","bottom"},names={"左边","右边","上边","下边"};SeekBar[] bars=new SeekBar[4];for(int i=0;i<4;i++){TextView text=new TextView(a);SeekBar bar=new SeekBar(a);bar.setMax(40);bar.setProgress(Math.round(value(p,keys[i])*100));text.setText(names[i]+" "+bar.getProgress()+"%");final String name=names[i];bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar s,int n,boolean user){text.setText(name+" "+n+"%");}public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}});body.addView(text);body.addView(bar);bars[i]=bar;}new AlertDialog.Builder(a).setTitle("HUD 边缘遮罩").setView(body).setPositiveButton("保存",(d,w)->{android.content.SharedPreferences.Editor e=p.edit();for(int i=0;i<4;i++)e.putInt(keys[i],bars[i].getProgress());e.apply();HudOutput.clear();HudOutput.resumed(a);InstrumentOutput.resumed(a);}).setNeutralButton("关闭遮罩",(d,w)->{p.edit().clear().apply();HudOutput.clear();HudOutput.resumed(a);InstrumentOutput.resumed(a);}).setNegativeButton("取消",null).show();}
}
